class Money {
  #cents;
  constructor(cents) { this.#cents = cents; }
  // the only operator hook the language offers: coercion to a PRIMITIVE
  [Symbol.toPrimitive](hint) { return hint === 'string' ? `${this.#cents}c` : this.#cents; }
  plus(other) { return new Money(this.#cents + other.#cents); }   // a + b cannot build a Money
}

const ComparableMethods = {
  compareTo(other) { return this.key() - other.key(); },
  isLessThan(other) { return this.compareTo(other) < 0; }
};
class Version {
  constructor(n) { this.n = n; }
  key() { return this.n; }
}
Object.assign(Version.prototype, ComparableMethods);   // compareTo, isLessThan, ...
